import{_ as t,o,c as s,ag as n}from"./chunks/framework.BZohXCq9.js";const u=JSON.parse('{"title":"Stripe Phase 2 – Files Changed & How the Code Works","description":"","frontmatter":{},"headers":[],"relativePath":"STRIPE_PHASE2_FILES_AND_FLOW.md","filePath":"STRIPE_PHASE2_FILES_AND_FLOW.md"}'),r={name:"STRIPE_PHASE2_FILES_AND_FLOW.md"};function a(d,e,i,c,l,h){return o(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="stripe-phase-2-–-files-changed-how-the-code-works" tabindex="-1">Stripe Phase 2 – Files Changed &amp; How the Code Works <a class="header-anchor" href="#stripe-phase-2-–-files-changed-how-the-code-works" aria-label="Permalink to &quot;Stripe Phase 2 – Files Changed &amp; How the Code Works&quot;">​</a></h1><p>This document lists <strong>every file</strong> that was changed for the Stripe T-48 / instant vs deferred payment flow and explains <strong>what each file does</strong> so you can follow the full flow in your codebase.</p><hr><h2 id="high-level-flow-what-happens-in-the-code" tabindex="-1">High-level flow (what happens in the code) <a class="header-anchor" href="#high-level-flow-what-happens-in-the-code" aria-label="Permalink to &quot;High-level flow (what happens in the code)&quot;">​</a></h2><ol><li><strong>Student clicks “Pay” on booking</strong> → Frontend calls <code>createBookingCheckoutSession</code>.</li><li><strong>Backend decides instant vs deferred</strong> using the 48h rule → Creates either a <strong>payment</strong> or <strong>setup</strong> Stripe Checkout session.</li><li><strong>Student is redirected to Stripe</strong> → Pays now (instant) or only saves card (deferred).</li><li><strong>Stripe redirects back</strong> with <code>?checkout=success</code> or <code>?checkout=setup_success</code> and <code>session_id</code>.</li><li><strong>Frontend</strong> calls either <code>completeBookingFromCheckout</code> (instant) or <code>completeDeferredBookingFromCheckout</code> (deferred).</li><li><strong>For deferred bookings</strong>, a <strong>scheduled job (T-48)</strong> runs every 5 minutes and charges each slot when “lesson start − 48 hours” has passed.</li><li><strong>Emails</strong> can be sent when T-48 charge needs 3DS (<code>payment_requires_action</code>) or fails (<code>payment_failed</code>).</li></ol><hr><h2 id="multi-slot-booking-how-payment-works-instant-vs-t-48" tabindex="-1">Multi-slot booking: how payment works (instant vs T-48) <a class="header-anchor" href="#multi-slot-booking-how-payment-works-instant-vs-t-48" aria-label="Permalink to &quot;Multi-slot booking: how payment works (instant vs T-48)&quot;">​</a></h2><p>When a student books <strong>multiple slots at once</strong> (e.g. 3 lessons), payment is handled as follows.</p><h3 id="instant-payment-pay-now-–-gap-≤-48h" tabindex="-1">Instant payment (pay now – gap ≤ 48h) <a class="header-anchor" href="#instant-payment-pay-now-–-gap-≤-48h" aria-label="Permalink to &quot;Instant payment (pay now – gap ≤ 48h)&quot;">​</a></h3><ul><li><strong>One charge for the whole booking</strong><ul><li>One Stripe <strong>Checkout Session</strong> (mode <code>payment</code>) is created with the <strong>total amount</strong> (e.g. 3 × CHF 90 = CHF 270).</li><li>Stripe creates a single <strong>PaymentIntent</strong> for that session and charges the full amount once.</li></ul></li><li><strong>After payment</strong><ul><li>Frontend calls <code>completeBookingFromCheckout(sessionId)</code>, which: <ul><li>Sets <code>booking.stripePaymentIntentId</code> to that one PaymentIntent ID.</li><li>Marks <strong>all slots</strong> in the booking as <code>paymentStatus: &quot;paid&quot;</code> and sets per-slot <code>chargeAmount</code>, <code>dspCommission</code>, <code>instructorAmount</code>.</li></ul></li><li>Slots do <strong>not</strong> get their own <code>paymentIntentId</code>; the booking has one <code>stripePaymentIntentId</code> for the entire payment.</li></ul></li></ul><p>So: <strong>multiple slots → one payment, one PaymentIntent, all slots marked paid together.</strong></p><h3 id="deferred-payment-save-card-–-gap-48h-charge-at-t-48" tabindex="-1">Deferred payment (save card – gap &gt; 48h, charge at T-48) <a class="header-anchor" href="#deferred-payment-save-card-–-gap-48h-charge-at-t-48" aria-label="Permalink to &quot;Deferred payment (save card – gap &gt; 48h, charge at T-48)&quot;">​</a></h3><ul><li><strong>At checkout</strong><ul><li>One Stripe <strong>Checkout Session</strong> (mode <code>setup</code>) is created. <strong>No charge</strong>; only the card is saved.</li><li>Webhook <code>checkout.session.completed</code> (or <code>completeDeferredBookingFromCheckout</code>) saves <code>stripeCustomerId</code> and <code>paymentMethod.paymentMethodId</code> on the booking.</li><li><strong>All slots</strong> stay <code>paymentStatus: &quot;pending_payment&quot;</code>; none have <code>paymentIntentId</code> yet.</li></ul></li><li><strong>At T-48 (48 hours before each lesson)</strong><ul><li>The <strong>T-48 job</strong> (<code>t48ChargeJob.js</code>) runs periodically. For each booking that has <code>pending_payment</code> slots and a saved payment method: <ul><li>It loops over <strong>each slot</strong> whose start time is within the T-48 window (lesson start − 48h ≤ now).</li><li>For <strong>each such slot</strong> it creates <strong>one PaymentIntent</strong> with: <ul><li>Amount = <strong>per-slot amount</strong> (e.g. totalAmount / numSlots).</li><li>Metadata: <code>bookingId</code>, <code>slotId</code>, <code>studentId</code>, <code>instructorId</code>.</li><li>Idempotency key: <code>t48-{bookingId}-{slotId}</code> (so the same slot is never charged twice).</li></ul></li><li>It charges that PaymentIntent (off-session). If it <strong>succeeds</strong> → slot is updated to <code>paid</code> and <code>slots.$.paymentIntentId</code> is set. If <strong>requires_action</strong> (3DS) → slot is set to <code>requires_action</code> and the student must complete payment (e.g. “Complete payment” in dashboard). If it <strong>fails</strong> → slot is set to <code>payment_failed</code> (retries up to max, then stop).</li></ul></li><li>Webhook <strong><code>payment_intent.succeeded</code></strong> finds the slot by <code>slots.paymentIntentId === pi.id</code> and marks that slot paid (idempotent).</li></ul></li></ul><p>So: <strong>multiple slots → one card saved at checkout; then one PaymentIntent per slot at T-48, each charged when its lesson is within 48 hours.</strong></p><h3 id="summary-table" tabindex="-1">Summary table <a class="header-anchor" href="#summary-table" aria-label="Permalink to &quot;Summary table&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Scenario</th><th>When payment happens</th><th>PaymentIntents</th><th>Where PI ID is stored</th></tr></thead><tbody><tr><td>Instant (multi-slot)</td><td>At checkout (one go)</td><td>1 for full booking amount</td><td><code>booking.stripePaymentIntentId</code></td></tr><tr><td>Deferred (multi-slot)</td><td>T-48 per slot</td><td>1 per slot (per-slot amount)</td><td><code>slot.paymentIntentId</code> (each slot)</td></tr></tbody></table><p>The “Complete payment” flow (for 3DS or retry after <code>payment_failed</code>) uses <strong>per-slot</strong> <code>getT48ClientSecret(bookingId, slotId)</code> and <code>completeT48SlotPayment(paymentIntentId)</code> because at T-48 each slot has its own PaymentIntent.</p><hr><h2 id="cancel-one-slot-and-refund-instant-payment-one-pi-for-3-slots" tabindex="-1">Cancel one slot and refund (instant payment: one PI for 3 slots) <a class="header-anchor" href="#cancel-one-slot-and-refund-instant-payment-one-pi-for-3-slots" aria-label="Permalink to &quot;Cancel one slot and refund (instant payment: one PI for 3 slots)&quot;">​</a></h2><p>When the student paid once for 3 slots (one PaymentIntent), cancelling and refunding <strong>one</strong> slot works as follows.</p><h3 id="_1-cancel-the-slot" tabindex="-1">1. Cancel the slot <a class="header-anchor" href="#_1-cancel-the-slot" aria-label="Permalink to &quot;1. Cancel the slot&quot;">​</a></h3><ul><li><strong>Student or instructor:</strong> <code>cancelBookingSlot(bookingId, slotId)</code> — marks that slot as <code>status: &quot;cancelled&quot;</code>, <code>booked: false</code>, sets <code>cancellationDate</code>. Other slots are unchanged. Booking status becomes <code>semi_cancelled</code> if some slots remain, or <code>cancelled</code> if all are cancelled.</li><li><strong>Admin:</strong> <code>cancelBookingAdmin</code> — same effect (slot cancelled, availability updated).</li></ul><p>No refund happens yet; the student must request a refund (or admin approves it).</p><h3 id="_2-refund-that-slot-only-partial-refund" tabindex="-1">2. Refund that slot only (partial refund) <a class="header-anchor" href="#_2-refund-that-slot-only-partial-refund" aria-label="Permalink to &quot;2. Refund that slot only (partial refund)&quot;">​</a></h3><ul><li><strong>Student:</strong> Calls <code>requestRefund(bookingId, slotId)</code>. Allowed only if the slot is <strong>cancelled</strong>, <strong>paid</strong>, and not already refunded/payout not yet done. Creates a <strong>RefundRequest</strong> (pending).</li><li><strong>Admin:</strong> When approving via <code>approveRefundRequest(id)</code> the code: <ol><li>Uses the <strong>same</strong> PaymentIntent as the whole booking: <code>booking.stripePaymentIntentId</code>.</li><li>Refunds <strong>only that slot’s amount</strong>: <code>createRefund({ paymentIntentId, amountCentimes: slot.chargeAmount in centimes })</code>. Stripe supports <strong>partial refunds</strong> on a single PaymentIntent, so only that slot’s share (e.g. CHF 90) goes back to the student’s card.</li><li>Reverses the <strong>instructor’s share for that slot</strong> from the original transfer: <code>getTransferIdFromPaymentIntent(booking.stripePaymentIntentId)</code> returns the one Transfer for the original charge; then <code>createTransferReversal({ transferId, amountCentimes: slot.instructorAmount in centimes })</code>. Stripe supports <strong>partial transfer reversals</strong>, so only that slot’s instructor share (e.g. CHF 72) is taken back from the instructor’s connected account.</li><li>Marks the slot as <code>status: &quot;refund&quot;</code>, <code>paymentStatus: &quot;refunded&quot;</code>, sets <code>refundedAt</code>, and records transactions (student refund, instructor reversal, platform commission reversal).</li></ol></li></ul><p>So: <strong>one PaymentIntent for 3 slots</strong> → cancel one slot → <strong>partial refund</strong> (one slot’s <code>chargeAmount</code>) + <strong>partial transfer reversal</strong> (one slot’s <code>instructorAmount</code>). The other two slots stay paid; payout for them is unchanged.</p><h3 id="requirements-for-this-to-work" tabindex="-1">Requirements for this to work <a class="header-anchor" href="#requirements-for-this-to-work" aria-label="Permalink to &quot;Requirements for this to work&quot;">​</a></h3><ul><li>Each slot must have <strong>per-slot amounts</strong> set when the booking is completed: <code>chargeAmount</code>, <code>instructorAmount</code>, <code>dspCommission</code> (e.g. from <code>completeBookingFromCheckout</code> or instant <code>createBooking</code>). The refund flow uses <code>slot.chargeAmount</code> and <code>slot.instructorAmount</code> for the partial refund and reversal.</li><li>Refund is blocked if the instructor has already been <strong>paid out</strong> for that slot (<code>slot.payoutId</code> set), because the transfer has already left the platform.</li></ul><hr><h2 id="_1-server-–-data-model" tabindex="-1">1. Server – Data model <a class="header-anchor" href="#_1-server-–-data-model" aria-label="Permalink to &quot;1. Server – Data model&quot;">​</a></h2><h3 id="server-src-models-studentbooking-model-js" tabindex="-1"><code>server/src/models/studentBooking.model.js</code> <a class="header-anchor" href="#server-src-models-studentbooking-model-js" aria-label="Permalink to &quot;`server/src/models/studentBooking.model.js`&quot;">​</a></h3><p><strong>Role:</strong> Defines the booking and slot schema used by all resolvers and jobs.</p><p><strong>Changes for Phase 2:</strong></p><ul><li><strong>Slot schema</strong><ul><li><strong><code>paymentStatus</code></strong> enum extended: added <code>payment_failed</code> and <code>requires_action</code> (in addition to <code>pending_payment</code>, <code>paid</code>, <code>refunded</code>).</li><li><strong><code>paymentIntentId</code></strong> (String): per-slot Stripe PaymentIntent ID, set when T-48 job charges that slot.</li><li><strong><code>chargedAt</code></strong> (Date): when the T-48 charge succeeded for this slot.</li></ul></li><li><strong>Booking <code>paymentMethod</code></strong><ul><li><strong><code>setupIntentId</code></strong> (String, optional): stored when the student completed Checkout in <strong>setup</strong> mode (deferred flow); links to the Stripe SetupIntent that saved the card.</li></ul></li></ul><p><strong>Why it matters:</strong> Deferred bookings are stored with <code>paymentMethod.paymentMethodId</code> (and optionally <code>setupIntentId</code>). Slots stay <code>pending_payment</code> until the T-48 job charges them, then become <code>paid</code>, <code>requires_action</code>, or <code>payment_failed</code>. All of that is persisted in this model.</p><hr><h2 id="_2-server-–-stripe-api" tabindex="-1">2. Server – Stripe API <a class="header-anchor" href="#_2-server-–-stripe-api" aria-label="Permalink to &quot;2. Server – Stripe API&quot;">​</a></h2><h3 id="server-src-services-stripeservice-js" tabindex="-1"><code>server/src/services/stripeService.js</code> <a class="header-anchor" href="#server-src-services-stripeservice-js" aria-label="Permalink to &quot;`server/src/services/stripeService.js`&quot;">​</a></h3><p><strong>Role:</strong> All direct Stripe API calls for bookings and payouts.</p><p><strong>Changes for Phase 2:</strong></p><ul><li><p><strong><code>createPaymentIntentForBooking(opts)</code></strong></p><ul><li>New option <strong><code>offSession</code></strong> (default <code>false</code>).</li><li>When <code>offSession: true</code>: sets <code>off_session: true</code> on the PaymentIntent and does <strong>not</strong> send <code>return_url</code> on confirm. Used when the T-48 job charges in the background (no browser).</li><li>When <code>offSession: false</code>: same as before (e.g. in-page or redirect flows with 3DS return URL).</li></ul></li><li><p><strong><code>createCheckoutSessionForBooking(opts)</code></strong></p><ul><li>New option <strong><code>mode</code></strong>: <code>&quot;payment&quot;</code> (default) or <code>&quot;setup&quot;</code>.</li><li><strong><code>mode: &quot;payment&quot;</code></strong>: same as before – creates a Checkout Session that collects payment immediately (line items + <code>payment_intent_data</code> with <code>transfer_data</code> to instructor).</li><li><strong><code>mode: &quot;setup&quot;</code></strong>: creates a Checkout Session that only <strong>saves the card</strong> (no charge): <code>mode: &quot;setup&quot;</code>, <code>payment_method_types: [&quot;card&quot;]</code>, <code>setup_intent_data.metadata</code>. Used for deferred bookings.</li><li><strong>Success URL:</strong> For <code>mode === &quot;setup&quot;</code> the success URL uses <code>checkout=setup_success</code> so the frontend can call <code>completeDeferredBookingFromCheckout</code>. For <code>mode === &quot;payment&quot;</code> it uses <code>checkout=success</code>.</li></ul></li><li><p><strong><code>retrieveCheckoutSession(sessionId)</code></strong></p><ul><li>Now expands both <strong><code>payment_intent</code></strong> and <strong><code>setup_intent</code></strong> so the resolver can read either the paid PaymentIntent (instant) or the succeeded SetupIntent (deferred) and its <code>payment_method</code>.</li></ul></li></ul><p><strong>Why it matters:</strong> This is the only place that talks to Stripe for “create session” and “create/confirm PaymentIntent”. The 48h logic lives in the resolver; this file only implements “payment session” vs “setup session” and “on-session” vs “off-session” PaymentIntent.</p><hr><h2 id="_3-server-–-graphql-api-resolvers-types" tabindex="-1">3. Server – GraphQL API (resolvers &amp; types) <a class="header-anchor" href="#_3-server-–-graphql-api-resolvers-types" aria-label="Permalink to &quot;3. Server – GraphQL API (resolvers &amp; types)&quot;">​</a></h2><h3 id="server-src-graphql-resolvers-studentbooking-resolver-js" tabindex="-1"><code>server/src/graphql/resolvers/studentBooking.resolver.js</code> <a class="header-anchor" href="#server-src-graphql-resolvers-studentbooking-resolver-js" aria-label="Permalink to &quot;`server/src/graphql/resolvers/studentBooking.resolver.js`&quot;">​</a></h3><p><strong>Role:</strong> Implements booking mutations and queries. This is where the 48h rule and instant vs deferred behaviour live.</p><p><strong>Changes for Phase 2:</strong></p><ul><li><p><strong><code>createBookingCheckoutSession</code></strong></p><ul><li><strong>48h rule:</strong> Computes the <strong>earliest</strong> slot start (<code>slot.date</code> + <code>slot.startTime</code>) and compares it to “now”.</li><li>If <code>earliestSlotStart - now &gt; 48 hours</code> → <strong>deferred</strong>: calls <code>createCheckoutSessionForBooking</code> with <strong><code>mode: &quot;setup&quot;</code></strong> and returns <strong><code>deferred: true</code></strong>.</li><li>If gap ≤ 48 hours → <strong>instant</strong>: calls with <strong><code>mode: &quot;payment&quot;</code></strong> and returns <strong><code>deferred: false</code></strong>.</li><li><strong>Console:</strong> Logs one line per request: <code>[createBookingCheckoutSession] Earliest slot: ..., gap X.Xh → DEFERRED (...)</code> or <code>INSTANT (...)</code>.</li><li>Metadata passed to Stripe always includes <code>bookingId</code>, <code>studentId</code>, <code>instructorId</code>; for setup we still create the booking in DB with status <code>&quot;pending&quot;</code> and slots <code>paymentStatus: &quot;pending_payment&quot;</code> before redirecting.</li></ul></li><li><p><strong><code>completeBookingFromCheckout(sessionId)</code></strong></p><ul><li><strong>Guard:</strong> Now requires <strong><code>session.mode === &quot;payment&quot;</code></strong> and <strong><code>session.payment_status === &quot;paid&quot;</code></strong>. If the session was actually a setup session (deferred), this returns an error so the frontend must use the other mutation.</li></ul></li><li><p><strong><code>completeDeferredBookingFromCheckout(sessionId)</code></strong> (new)</p><ul><li>Loads the Checkout session with <strong><code>expand: [&quot;setup_intent&quot;]</code></strong> (via <code>retrieveCheckoutSession</code>).</li><li>Ensures <strong><code>session.mode === &quot;setup&quot;</code></strong> and <strong><code>session.setup_intent.status === &quot;succeeded&quot;</code></strong>.</li><li>Reads <strong><code>payment_method</code></strong> from the SetupIntent (the saved card).</li><li>Finds the booking by <strong><code>session.metadata.bookingId</code></strong>, checks the logged-in user is the student.</li><li>Updates the booking: <strong><code>status: &quot;confirmed&quot;</code></strong>, <strong><code>paymentMethod.paymentMethodId</code></strong> = that payment method, <strong><code>paymentMethod.setupIntentId</code></strong> = SetupIntent id. All slots stay <strong><code>paymentStatus: &quot;pending_payment&quot;</code></strong>.</li><li>Does <strong>not</strong> create any PaymentIntent or transactions; that happens later in the T-48 job.</li><li>Sends “booking created” emails and socket notification like the instant flow.</li></ul></li></ul><p><strong>Why it matters:</strong> All “should we charge now or later?” and “finalise booking after Stripe” logic is here. The Stripe service only creates sessions and PaymentIntents; this file decides which session type to create and how to complete the booking after redirect.</p><h3 id="server-src-graphql-typedefs-studentbooking-typedefs-js" tabindex="-1"><code>server/src/graphql/typeDefs/studentBooking.typeDefs.js</code> <a class="header-anchor" href="#server-src-graphql-typedefs-studentbooking-typedefs-js" aria-label="Permalink to &quot;`server/src/graphql/typeDefs/studentBooking.typeDefs.js`&quot;">​</a></h3><p><strong>Role:</strong> GraphQL schema for bookings (types and mutations).</p><p><strong>Changes for Phase 2:</strong></p><ul><li><strong><code>CreateBookingCheckoutPayload</code></strong><ul><li>New field: <strong><code>deferred: Boolean</code></strong> so the frontend can show different copy or handle redirects differently if needed.</li></ul></li><li><strong>Mutation</strong><ul><li><strong><code>completeDeferredBookingFromCheckout(sessionId: String!): StudentBooking!</code></strong> – used after the student returns from Stripe when they only saved their card (deferred flow).</li></ul></li></ul><p><strong>Why it matters:</strong> The API contract for “create checkout” and “complete deferred booking” is defined here; resolvers implement it.</p><hr><h2 id="_4-server-–-t-48-charge-job" tabindex="-1">4. Server – T-48 charge job <a class="header-anchor" href="#_4-server-–-t-48-charge-job" aria-label="Permalink to &quot;4. Server – T-48 charge job&quot;">​</a></h2><h3 id="server-src-jobs-t48chargejob-js" tabindex="-1"><code>server/src/jobs/t48ChargeJob.js</code> <a class="header-anchor" href="#server-src-jobs-t48chargejob-js" aria-label="Permalink to &quot;`server/src/jobs/t48ChargeJob.js`&quot;">​</a></h3><p><strong>Role:</strong> Scheduled job that charges <strong>per-slot</strong> for deferred bookings when “lesson start − 48 hours” has passed. Uses the card saved at booking (SetupIntent) to create and confirm a PaymentIntent per slot.</p><p><strong>What it does (no other file contains this logic):</strong></p><ul><li>Runs on an interval (see <code>index.js</code>).</li><li>Finds all bookings that have at least one slot with <strong><code>paymentStatus: &quot;pending_payment&quot;</code></strong> and a saved <strong><code>paymentMethod.paymentMethodId</code></strong>.</li><li>For each such booking, loads instructor (for commission and Stripe Connect account).</li><li>For each slot with <strong><code>paymentStatus === &quot;pending_payment&quot;</code></strong>: <ul><li>Computes <strong>slot start</strong> = <code>new Date(slot.date + &#39;T&#39; + slot.startTime)</code> and <strong>charge time</strong> = slot start − 48 hours.</li><li>If <strong>charge time &gt; now</strong>, skips (not yet in T-48 window).</li><li>If <strong>charge time ≤ now</strong>: calls <strong><code>createPaymentIntentForBooking</code></strong> with: <ul><li>amount = that slot’s share of the booking total,</li><li><strong><code>paymentMethodId</code></strong> from the booking,</li><li><strong><code>offSession: true</code></strong>,</li><li><strong><code>transferData</code></strong> to instructor’s Connect account,</li><li><strong>metadata</strong>: <code>bookingId</code>, <code>slotId</code>, <code>studentId</code>, <code>instructorId</code>.</li></ul></li></ul></li><li><strong>If PaymentIntent status is <code>succeeded</code>:</strong><ul><li>Updates the slot: <code>paymentStatus: &quot;paid&quot;</code>, <code>paymentIntentId</code>, <code>chargedAt</code>, <code>chargeAmount</code>, <code>dspCommission</code>, <code>instructorAmount</code>, <code>payoutStatus: &quot;not_applicable&quot;</code>.</li><li>Creates four transactions (student debit, platform receipt, instructor share, platform commission) for that slot.</li></ul></li><li><strong>If <code>requires_action</code> (3DS):</strong><ul><li>Sets slot <strong><code>paymentStatus: &quot;requires_action&quot;</code></strong> and stores <strong><code>paymentIntentId</code></strong>.</li><li>(You can later send the “payment_requires_action” email from here or from a separate step.)</li></ul></li><li><strong>If payment fails or other status:</strong><ul><li>Sets slot <strong><code>paymentStatus: &quot;payment_failed&quot;</code></strong>.</li><li>(You can send the “payment_failed” email from here.)</li></ul></li></ul><p><strong>Console logs added:</strong><br> Tick at start, “no bookings” or “found N bookings”, per-slot “not yet in window” / “Charging slot…” / “payment succeeded” / “requires_action” / “payment_failed”, and a final “Done. charged=X, requires_action=Y, failed=Z”.</p><p><strong>Why it matters:</strong> This is the only place that performs the actual “charge 48 hours before lesson” behaviour for deferred bookings. It uses the same commission split and transaction creation as the instant flow, but per slot and triggered by time.</p><hr><h2 id="_5-server-–-job-scheduling" tabindex="-1">5. Server – Job scheduling <a class="header-anchor" href="#_5-server-–-job-scheduling" aria-label="Permalink to &quot;5. Server – Job scheduling&quot;">​</a></h2><h3 id="server-src-index-js" tabindex="-1"><code>server/src/index.js</code> <a class="header-anchor" href="#server-src-index-js" aria-label="Permalink to &quot;`server/src/index.js`&quot;">​</a></h3><p><strong>Role:</strong> App entry point; starts the server and schedules background jobs.</p><p><strong>Changes for Phase 2:</strong></p><ul><li><strong>Require:</strong> <code>const { runT48ChargeJob } = require(&quot;./jobs/t48ChargeJob&quot;);</code></li><li><strong>Schedule T-48 job:</strong><ul><li><strong>Interval:</strong> <code>T48_JOB_INTERVAL_MS = 5 * 60 * 1000</code> (5 minutes). You can change this for production (e.g. 15–30 min).</li><li><strong>setInterval:</strong> calls <code>runT48ChargeJob()</code> every 5 minutes and logs errors.</li><li><strong>Initial run:</strong> <code>runT48ChargeJob()</code> once on startup.</li></ul></li></ul><p><strong>Why it matters:</strong> Without this, the T-48 job would never run; deferred bookings would stay <code>pending_payment</code> forever.</p><hr><h2 id="_6-server-–-payout-job-logging-only" tabindex="-1">6. Server – Payout job (logging only) <a class="header-anchor" href="#_6-server-–-payout-job-logging-only" aria-label="Permalink to &quot;6. Server – Payout job (logging only)&quot;">​</a></h2><h3 id="server-src-jobs-payoutjob-js" tabindex="-1"><code>server/src/jobs/payoutJob.js</code> <a class="header-anchor" href="#server-src-jobs-payoutjob-js" aria-label="Permalink to &quot;`server/src/jobs/payoutJob.js`&quot;">​</a></h3><p><strong>Role:</strong> Existing job that pays out instructors (e.g. 3 days after lesson completion). <strong>No change to payment/T-48 logic.</strong></p><p><strong>Changes for Phase 2:</strong></p><ul><li><strong>Console logs:</strong><ul><li>At start: <code>[PayoutJob] Tick at &lt;time&gt; — checking for slots eligible for instructor payout</code>.</li><li>At end: <code>[PayoutJob] Done. processed=X, errors=Y</code>.</li></ul></li></ul><p><strong>Why it matters:</strong> Lets you see in the server log that this cron is running; helps distinguish T-48 logs from payout logs.</p><hr><h2 id="_7-server-–-emails-3ds-and-failure" tabindex="-1">7. Server – Emails (3DS and failure) <a class="header-anchor" href="#_7-server-–-emails-3ds-and-failure" aria-label="Permalink to &quot;7. Server – Emails (3DS and failure)&quot;">​</a></h2><h3 id="server-src-utils-sendotpemail-js" tabindex="-1"><code>server/src/utils/SendOtpEmail.js</code> <a class="header-anchor" href="#server-src-utils-sendotpemail-js" aria-label="Permalink to &quot;`server/src/utils/SendOtpEmail.js`&quot;">​</a></h3><p><strong>Role:</strong> Sends transactional emails (booking created, cancelled, etc.). Used for notifications when T-48 charge needs 3DS or fails.</p><p><strong>Changes for Phase 2:</strong></p><ul><li><strong><code>sendBookingEmail(recipients, bookingData, type)</code></strong><ul><li>New <strong><code>type</code></strong> values: <ul><li><strong><code>payment_requires_action</code></strong>: “Your lesson is in 48 hours; we need you to complete authentication for your payment.” (You can add a link to your “complete payment” page when you build it.)</li><li><strong><code>payment_failed</code></strong>: “Payment for your lesson could not be completed. Please update your payment method or try again.”</li></ul></li></ul></li></ul><p><strong>Note:</strong> The <strong>T-48 job</strong> does not call these yet. When you want to notify students, call <code>sendBookingEmail</code> (or <code>notifyBookingParties</code>) from the T-48 job when a slot is set to <code>requires_action</code> or <code>payment_failed</code>, passing the right <code>type</code> and slot/booking data.</p><p><strong>Why it matters:</strong> Central place for all booking-related email copy; Phase 2 adds the two new cases for 3DS and failure.</p><hr><h2 id="_8-server-–-stripe-webhook" tabindex="-1">8. Server – Stripe webhook <a class="header-anchor" href="#_8-server-–-stripe-webhook" aria-label="Permalink to &quot;8. Server – Stripe webhook&quot;">​</a></h2><h3 id="server-src-routes-stripewebhook-routes-js" tabindex="-1"><code>server/src/routes/stripeWebhook.routes.js</code> <a class="header-anchor" href="#server-src-routes-stripewebhook-routes-js" aria-label="Permalink to &quot;`server/src/routes/stripeWebhook.routes.js`&quot;">​</a></h3><p><strong>Role:</strong> Receives Stripe webhooks (e.g. <code>payment_intent.succeeded</code>). Used for idempotency or updating state when payment completes asynchronously (e.g. after 3DS).</p><p><strong>Changes for Phase 2:</strong></p><ul><li><strong><code>payment_intent.succeeded</code> (platform, no Connect account):</strong><ul><li>Still looks up booking by <strong><code>stripePaymentIntentId</code></strong> (legacy instant flow, one PI per booking).</li><li>Comment added: for <strong>T-48 per-slot</strong> flow, the job already updates the slot and creates transactions when the charge succeeds, so the webhook does not need to do extra work for those. If you later add a “complete payment” page for 3DS, you can either rely on the frontend calling a “confirm slot paid” mutation after success or handle <code>payment_intent.succeeded</code> here to set the slot to <code>paid</code> and create transactions (idempotent).</li></ul></li></ul><p><strong>Why it matters:</strong> Keeps webhook behaviour clear and avoids double-processing; documents that T-48 success is primarily handled in the job.</p><hr><h2 id="_9-frontend-–-graphql-mutations" tabindex="-1">9. Frontend – GraphQL mutations <a class="header-anchor" href="#_9-frontend-–-graphql-mutations" aria-label="Permalink to &quot;9. Frontend – GraphQL mutations&quot;">​</a></h2><h3 id="frontend-src-graphql-mutations-studentbooking-ts" tabindex="-1"><code>Frontend/src/graphql/mutations/studentBooking.ts</code> <a class="header-anchor" href="#frontend-src-graphql-mutations-studentbooking-ts" aria-label="Permalink to &quot;`Frontend/src/graphql/mutations/studentBooking.ts`&quot;">​</a></h3><p><strong>Role:</strong> GraphQL document definitions for booking mutations and queries used by the UI.</p><p><strong>Changes for Phase 2:</strong></p><ul><li><strong><code>CREATE_BOOKING_CHECKOUT_SESSION</code></strong><ul><li>Selection set extended with <strong><code>deferred</code></strong> so the client can read whether this checkout is instant or deferred (e.g. for messaging or analytics).</li></ul></li><li><strong><code>COMPLETE_DEFERRED_BOOKING_FROM_CHECKOUT</code></strong> (new) <ul><li>Mutation: <strong><code>completeDeferredBookingFromCheckout(sessionId: $sessionId)</code></strong>.</li><li>Returns the same booking shape as the other completion mutation (<code>_id</code>, <code>status</code>, <code>slots</code>, <code>totalAmount</code>, <code>finalAmount</code>, <code>createdAt</code>, <code>updatedAt</code>).</li></ul></li></ul><p><strong>Why it matters:</strong> The frontend can only call “complete deferred booking” and show the right success message if this mutation and the <code>deferred</code> field are defined and requested here.</p><hr><h2 id="_10-frontend-–-booking-details-page-redirect-handling" tabindex="-1">10. Frontend – Booking details page (redirect handling) <a class="header-anchor" href="#_10-frontend-–-booking-details-page-redirect-handling" aria-label="Permalink to &quot;10. Frontend – Booking details page (redirect handling)&quot;">​</a></h2><h3 id="frontend-src-pages-private-student-dashboard-bookingdetails-tsx" tabindex="-1"><code>Frontend/src/pages/private/student-dashboard/bookingDetails.tsx</code> <a class="header-anchor" href="#frontend-src-pages-private-student-dashboard-bookingdetails-tsx" aria-label="Permalink to &quot;`Frontend/src/pages/private/student-dashboard/bookingDetails.tsx`&quot;">​</a></h3><p><strong>Role:</strong> Page where the student sees booking summary and clicks “Pay” (redirect to Stripe). Also the <strong>redirect target</strong> after Stripe Checkout (success or cancel).</p><p><strong>Changes for Phase 2:</strong></p><ul><li><strong>Imports:</strong> Added <strong><code>COMPLETE_DEFERRED_BOOKING_FROM_CHECKOUT</code></strong>.</li><li><strong>Mutation hook:</strong> <strong><code>useMutation(COMPLETE_DEFERRED_BOOKING_FROM_CHECKOUT, ...)</code></strong> to call the new resolver when the user returns from a <strong>setup</strong> session.</li><li><strong>URL handling (e.g. in <code>useEffect</code>):</strong><ul><li><strong><code>checkout=success</code> + <code>session_id</code></strong> → call <strong><code>completeBookingFromCheckout(sessionId)</code></strong> (instant payment). Toast: “Booking confirmed! Payment successful.”</li><li><strong><code>checkout=setup_success</code> + <code>session_id</code></strong> → call <strong><code>completeDeferredBookingFromCheckout(sessionId)</code></strong> (deferred, card saved). Toast: “Card saved successfully. We will charge you 48 hours before each lesson.”</li><li>In both cases, then clear query params and navigate to the bookings list (or similar).</li></ul></li></ul><p><strong>Why it matters:</strong> Stripe always redirects to the same path (e.g. <code>/student-dashboard/booking-details</code>); the <strong>query param</strong> (<code>checkout=success</code> vs <code>checkout=setup_success</code>) is what tells the app which mutation to call. The backend sets that param via the success URL in <code>stripeService.js</code> (see above).</p><hr><h2 id="_11-docs-and-testing" tabindex="-1">11. Docs and testing <a class="header-anchor" href="#_11-docs-and-testing" aria-label="Permalink to &quot;11. Docs and testing&quot;">​</a></h2><h3 id="server-testing-t48-md" tabindex="-1"><code>server/TESTING_T48.md</code> <a class="header-anchor" href="#server-testing-t48-md" aria-label="Permalink to &quot;`server/TESTING_T48.md`&quot;">​</a></h3><p><strong>Role:</strong> Short testing guide: what to look for in server logs, how to test deferred (T-48) vs instant (which dates to book), and how to test the T-48 job without waiting 48 hours (e.g. temporarily use 2 minutes).</p><h3 id="docs-stripe-phase2-files-and-flow-md-this-file" tabindex="-1"><code>docs/STRIPE_PHASE2_FILES_AND_FLOW.md</code> (this file) <a class="header-anchor" href="#docs-stripe-phase2-files-and-flow-md-this-file" aria-label="Permalink to &quot;`docs/STRIPE_PHASE2_FILES_AND_FLOW.md` (this file)&quot;">​</a></h3><p><strong>Role:</strong> Single place that lists every file touched for Phase 2 Stripe and explains what each part does so you can trace the full flow in the code.</p><hr><h2 id="quick-reference-which-file-does-what" tabindex="-1">Quick reference: which file does what <a class="header-anchor" href="#quick-reference-which-file-does-what" aria-label="Permalink to &quot;Quick reference: which file does what&quot;">​</a></h2><table tabindex="0"><thead><tr><th>What you want to understand / change</th><th>File(s) to look at</th></tr></thead><tbody><tr><td>When we charge (48h rule, instant vs deferred)</td><td><code>studentBooking.resolver.js</code> → <code>createBookingCheckoutSession</code></td></tr><tr><td>How we create “pay now” vs “save card” session</td><td><code>stripeService.js</code> → <code>createCheckoutSessionForBooking</code> (mode)</td></tr><tr><td>What we store per slot (payment status, PI id, chargedAt)</td><td><code>studentBooking.model.js</code> (slot schema)</td></tr><tr><td>What we store for “saved card” on booking</td><td><code>studentBooking.model.js</code> (paymentMethod), <code>studentBooking.resolver.js</code> → <code>completeDeferredBookingFromCheckout</code></td></tr><tr><td>When and how T-48 charges run</td><td><code>t48ChargeJob.js</code>, <code>index.js</code> (schedule)</td></tr><tr><td>How we charge in the background (off-session)</td><td><code>stripeService.js</code> → <code>createPaymentIntentForBooking(offSession: true)</code></td></tr><tr><td>What happens after Stripe redirect (instant)</td><td><code>studentBooking.resolver.js</code> → <code>completeBookingFromCheckout</code></td></tr><tr><td>What happens after Stripe redirect (deferred)</td><td><code>studentBooking.resolver.js</code> → <code>completeDeferredBookingFromCheckout</code></td></tr><tr><td>How frontend chooses which completion to call</td><td><code>bookingDetails.tsx</code> (checkout=success vs setup_success)</td></tr><tr><td>Success URL for setup vs payment</td><td><code>stripeService.js</code> (checkoutParam for success URL)</td></tr><tr><td>Emails for 3DS / payment failed</td><td><code>SendOtpEmail.js</code> (payment_requires_action, payment_failed)</td></tr><tr><td>Webhook when payment succeeds</td><td><code>stripeWebhook.routes.js</code> (payment_intent.succeeded)</td></tr></tbody></table><hr><h2 id="end-to-end-trace-deferred-booking" tabindex="-1">End-to-end trace (deferred booking) <a class="header-anchor" href="#end-to-end-trace-deferred-booking" aria-label="Permalink to &quot;End-to-end trace (deferred booking)&quot;">​</a></h2><ol><li>User clicks Pay → <strong>bookingDetails.tsx</strong> calls <strong>createBookingCheckoutSession</strong> (GraphQL).</li><li><strong>studentBooking.resolver.js</strong> → <strong>createBookingCheckoutSession</strong>: computes earliest slot, gap &gt; 48h → <strong>isDeferred = true</strong>.</li><li>Resolver calls <strong>stripeService.createCheckoutSessionForBooking</strong> with <strong>mode: &quot;setup&quot;</strong> and <strong>metadata.bookingId</strong>.</li><li><strong>stripeService</strong> builds success URL with <strong>checkout=setup_success</strong> and creates Stripe Session (setup mode).</li><li>User is redirected to Stripe, saves card, redirected back to app with <strong>?checkout=setup_success&amp;session_id=...</strong>.</li><li><strong>bookingDetails.tsx</strong> sees <strong>checkout=setup_success</strong> → calls <strong>completeDeferredBookingFromCheckout(sessionId)</strong>.</li><li><strong>studentBooking.resolver.js</strong> → <strong>completeDeferredBookingFromCheckout</strong>: loads session (with setup_intent), gets payment_method, finds booking by metadata.bookingId, sets <strong>paymentMethod.paymentMethodId</strong> and <strong>status: &quot;confirmed&quot;</strong>, slots stay <strong>pending_payment</strong>.</li><li>Every 5 minutes <strong>index.js</strong> runs <strong>runT48ChargeJob</strong>.</li><li><strong>t48ChargeJob.js</strong>: finds bookings with <strong>pending_payment</strong> slots and <strong>paymentMethod.paymentMethodId</strong>. For each slot where <strong>slotStart − 48h ≤ now</strong>, calls <strong>stripeService.createPaymentIntentForBooking(..., offSession: true)</strong>. On success, updates slot to <strong>paid</strong> and creates transactions; on <strong>requires_action</strong> sets <strong>requires_action</strong> and stores <strong>paymentIntentId</strong>; on failure sets <strong>payment_failed</strong>.</li></ol><p>That’s the full path through the code for a deferred (T-48) booking.</p>',118)])])}const p=t(r,[["render",a]]);export{u as __pageData,p as default};
